[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "mortgage-calculator-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "mortgage-calculator-surface",
      "components": [
        {
          "id": "root",
          "type": "Card",
          "properties": {
            "padding": "large"
          },
          "children": [
            {
              "id": "main_column",
              "type": "Column",
              "properties": {
                "spacing": "medium"
              },
              "children": [
                {
                  "id": "summary_header",
                  "type": "Text",
                  "properties": {
                    "text": "Summary of Mortgage Calculation",
                    "style": "headline-medium"
                  }
                },
                {
                  "id": "summary_row",
                  "type": "Row",
                  "properties": {
                    "spacing": "medium",
                    "verticalAlignment": "center"
                  },
                  "children": [
                    {
                      "id": "summary_icon",
                      "type": "Icon",
                      "properties": {
                        "assetPath": "/icons/finance.png",
                        "size": "large"
                      }
                    },
                    {
                      "id": "summary_text_col",
                      "type": "Column",
                      "children": [
                        {
                          "id": "monthly_payment_text",
                          "type": "Text",
                          "properties": {
                            "text": "Your estimated monthly payment is **$2,203.95**."
                          }
                        },
                        {
                          "id": "total_interest_text",
                          "type": "Text",
                          "properties": {
                            "text": "The total interest paid over the 30-year loan will be **$433,422.00**."
                          }
                        }
                      ]
                    }
                  ]
                },
                {
                  "id": "main_divider",
                  "type": "Divider"
                },
                {
                  "id": "details_tabs",
                  "type": "Tabs",
                  "children": [
                    {
                      "id": "details_tab",
                      "type": "Tab",
                      "properties": {
                        "label": "Mortgage Details"
                      },
                      "children": [
                        {
                          "id": "details_list",
                          "type": "List",
                          "children": [
                            {
                              "id": "detail_item_1",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "detail_row_1",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "detail_label_1",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Home Price"
                                      }
                                    },
                                    {
                                      "id": "detail_value_1",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$450,000"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "detail_item_2",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "detail_row_2",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "detail_label_2",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Down Payment (20%)"
                                      }
                                    },
                                    {
                                      "id": "detail_value_2",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$90,000"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "detail_item_3",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "detail_row_3",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "detail_label_3",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Loan Amount (Principal)"
                                      }
                                    },
                                    {
                                      "id": "detail_value_3",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$360,000"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "detail_item_4",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "detail_row_4",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "detail_label_4",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Annual Interest Rate"
                                      }
                                    },
                                    {
                                      "id": "detail_value_4",
                                      "type": "Text",
                                      "properties": {
                                        "text": "6.25%"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "detail_item_5",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "detail_row_5",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "detail_label_5",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Loan Term"
                                      }
                                    },
                                    {
                                      "id": "detail_value_5",
                                      "type": "Text",
                                      "properties": {
                                        "text": "30 years (360 months)"
                                      }
                                    }
                                  ]
                                }
                              ]
                            }
                          ]
                        }
                      ]
                    },
                    {
                      "id": "steps_tab",
                      "type": "Tab",
                      "properties": {
                        "label": "Calculation Steps"
                      },
                      "children": [
                        {
                          "id": "steps_column",
                          "type": "Column",
                          "properties": {
                            "spacing": "medium"
                          },
                          "children": [
                            {
                              "id": "step_1",
                              "type": "Text",
                              "properties": {
                                "text": "**1. Determine the Loan Amount:**\n$450,000 (Home Price) - $90,000 (Down Payment) = $360,000"
                              }
                            },
                            {
                              "id": "step_2",
                              "type": "Text",
                              "properties": {
                                "text": "**2. Calculate Monthly Interest Rate:**\n6.25% annual rate / 12 months = 0.005208333 monthly rate"
                              }
                            },
                            {
                              "id": "step_3",
                              "type": "Text",
                              "properties": {
                                "text": "**3. Calculate Monthly Mortgage Payment:**\nUsing formula: M = P [ i(1 + i)^n ] / [ (1 + i)^n – 1]\nResult: $2,203.95"
                              }
                            },
                            {
                              "id": "step_4",
                              "type": "Text",
                              "properties": {
                                "text": "**4. Calculate Total Amount Paid:**\n$2,203.95 (Monthly Payment) * 360 (Total Payments) = $793,422.00"
                              }
                            },
                            {
                              "id": "step_5",
                              "type": "Text",
                              "properties": {
                                "text": "**5. Calculate Total Interest Paid:**\n$793,422.00 (Total Amount Paid) - $360,000 (Principal Loan Amount) = $433,422.00"
                              }
                            }
                          ]
                        }
                      ]
                    },
                    {
                      "id": "figures_tab",
                      "type": "Tab",
                      "properties": {
                        "label": "Key Figures"
                      },
                      "children": [
                        {
                          "id": "figures_list",
                          "type": "List",
                          "children": [
                            {
                              "id": "figure_item_1",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "figure_row_1",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "figure_label_1",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Monthly Payment"
                                      }
                                    },
                                    {
                                      "id": "figure_value_1",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$2,203.95"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "figure_item_2",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "figure_row_2",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "figure_label_2",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Total Principal Paid"
                                      }
                                    },
                                    {
                                      "id": "figure_value_2",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$360,000.00"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "figure_item_3",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "figure_row_3",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "figure_label_3",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Total Interest Paid"
                                      }
                                    },
                                    {
                                      "id": "figure_value_3",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$433,422.00"
                                      }
                                    }
                                  ]
                                }
                              ]
                            },
                            {
                              "id": "figure_item_4",
                              "type": "ListItem",
                              "children": [
                                {
                                  "id": "figure_row_4",
                                  "type": "Row",
                                  "properties": {
                                    "horizontalAlignment": "space-between"
                                  },
                                  "children": [
                                    {
                                      "id": "figure_label_4",
                                      "type": "Text",
                                      "properties": {
                                        "text": "Total Amount Paid"
                                      }
                                    },
                                    {
                                      "id": "figure_value_4",
                                      "type": "Text",
                                      "properties": {
                                        "text": "$793,422.00"
                                      }
                                    }
                                  ]
                                }
                              ]
                            }
                          ]
                        }
                      ]
                    }
                  ]
                },
                {
                  "id": "actions_divider",
                  "type": "Divider"
                },
                {
                  "id": "actions_header",
                  "type": "Text",
                  "properties": {
                    "text": "Quick Actions",
                    "style": "title-medium"
                  }
                },
                {
                  "id": "actions_row",
                  "type": "Row",
                  "properties": {
                    "spacing": "medium"
                  },
                  "children": [
                    {
                      "id": "button_options",
                      "type": "Button",
                      "properties": {
                        "label": "Explore Options",
                        "style": "outlined",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "args": {
                            "url": "https://example.com/mortgage-options"
                          }
                        }
                      }
                    },
                    {
                      "id": "button_refinance",
                      "type": "Button",
                      "properties": {
                        "label": "Refinance Calculator",
                        "style": "outlined",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "args": {
                            "url": "https://example.com/refinance-calculator"
                          }
                        }
                      }
                    },
                    {
                      "id": "button_schedule",
                      "type": "Button",
                      "properties": {
                        "label": "Amortization Schedule",
                        "style": "outlined",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "args": {
                            "url": "https://example.com/amortization-schedule"
                          }
                        }
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
